#!/usr/bin/env python3
"""
Round 125b (culprits), 2 October 2026. Needs round 124b.

Dots stay visible close in; named water culprits with their sources.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

HEAD = "## Round 125b (2 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round125b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 124b" not in text:
        sys.exit("round125b: round 124b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round125b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round125b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round125b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


NOTE = '## Round 125b (2 October)\n\nNeeds round 124b. Tiles patch round125b_tiles.py beside it. No app.js?v= bump.\n\n- Points close in: past zoom 12 the glow is gone and the dot alone shows; it\n  now gains a thin light rim (addHud), so dull-coloured rows (development\n  projects) stay visible at city level. Asked 2 October.\n- water_cases: named companies a government body found or ruled to have taken\n  or depleted water (BlueTriton, Fondomonte/Almarai, Coca-Cola Plachimada),\n  each with its source; tiles water_cases.py places them by Nominatim.\n\n'
DIFF = ""

if __name__ == "__main__":
    main()
